var date = new Date();
date.setDate(date.getDate() + 365);
var futureYear = date.getFullYear();
var futureMonth = date.toLocaleString("default", {
  month: "long"
});
var futureDay = date.getDate();
cy.log("Future year to select: " + futureYear);
cy.log("Future monthe to select: " + futureMonth);
cy.log("Future day to select: " + futureDay);
function selectMonthAndYear() {
  cy.get('.datepicker-dropdown').find('.datepicker-switch').first().then(currenDate => {
    if (!currenDate.text().includes(futureYear)) {
      cy.get('.next').first().click();
      selectMonthAndYear();
    }
  }).then(() => {
    cy.get('.datepicker-dropdown').find('.datepicker-switch').first().then(currenDate => {
      if (!currenDate.text().includes(futureMonth)) {
        cy.get('.next').first().click();
        selectMonthAndYear();
      }
    });
  });
}
function selectFutureDay() {
  cy.get('[class="day"]').contains(futureDay).click();
}
selectMonthAndYear();
selectFutureDay();

